package com.opensocket.aievent.core.iam.persistence.repository;
import static com.opensocket.aievent.core.iam.persistence.repository.RowValues.*;import com.opensocket.aievent.core.iam.authentication.application.port.out.AuthenticationSubjectPort;import com.opensocket.aievent.core.iam.authentication.domain.*;import com.opensocket.aievent.core.iam.persistence.dao.IamAuthenticationDao;import com.opensocket.aievent.database.persistence.spi.DatabaseRepositoryAdapter;import java.util.*;
@DatabaseRepositoryAdapter public class MybatisAuthenticationSubjectAdapter implements AuthenticationSubjectPort{private final IamAuthenticationDao dao;public MybatisAuthenticationSubjectAdapter(IamAuthenticationDao dao){this.dao=dao;}public Optional<Subject>findByNormalizedUsername(String username){if("root".equals(username))return findRoot();return Optional.ofNullable(dao.findUserSubject(username)).map(r->new Subject(CredentialSubjectType.HUMAN_USER,string(r,"subjectId"),string(r,"username"),string(r,"status"),bool(r,"mfaRequired")));}public Optional<Subject>findRoot(){return Optional.ofNullable(dao.findRootSubject()).map(r->new Subject(CredentialSubjectType.INSTANCE_ROOT,string(r,"subjectId"),string(r,"username"),string(r,"status"),true));}public void requireTenantMembership(String userId,String tenantId){if(dao.countActiveTenantMembership(tenantId,userId)!=1)throw new AuthenticationDomainException(AuthenticationReasonCode.AUTH_TENANT_MEMBERSHIP_REQUIRED,"Active tenant membership is required");}}
